 78	async fn launch_server(state : Json) -> Json {
 79	  let root = required(state, "projectRoot")
 80	  let port = reserve_server_port(state)
 81	  let configured_env = field(state, "serverEnv").unwrap_or(Json::empty_object())
 82	  let diagnostic_env = Json::empty_object()
 83	  if configured_env is Json::Object(values) {
 84	    for name, value in values {
 85	      if value is Json::String(text) {
 86	        set_field(diagnostic_env, name, Json::string(redact_credentials(text)))
 87	      }
 88	    }
 89	  }
 90	  let recording = workspace_recording(state)
 91	  let script = (if field(state, "orcaVolume") is Some(_) {
 92	      "export ORCA_USER_DATA_PATH=/workspaces/.orca/.profile; "
 93	    } else {
 94	      ""
 95	    }) +
 96	    server_launch_script(root, port, configured_env, recording~)
 97	  let (status, raw_output, detail) = command_result(
 98	    workspace_program(state, "ssh"),
 99	    mux_ssh_args(state) + [script],
100	    "orca-serve",
101	    environment=workspace_environment(state),
102	    cwd?=workspace_directory(state).map(path => path[:]),
103	  )
104	  let mut output = raw_output
105	  if recording {
106	    let mut observed = None
107	    let mut truncated = Json::array([])
108	    let mut observation_error = false
109	    if raw_output.split_once("\n") is Some((first, remaining)) {
110	      let event = @json.parse(first.to_owned()) catch { _ => Json::null() }
111	      if field(event, "kind") == Some(Json::string("result")) &&
112	        field(event, "serverEnvironment") is Some(value) {
113	        observed = Some(value)
114	        truncated = field(event, "truncated").unwrap_or(Json::array([]))
115	        observation_error = field(event, "observationError") ==
116	          Some(Json::boolean(true))
117	        output = remaining.to_owned()
118	      }
119	    }
120	    let complete = (
121	        configured_env == Json::empty_object() || observed is Some(_)
122	      ) &&
123	      truncated == Json::array([])
124	    save_diagnostic(
125	      "server-environment",
126	      if complete {
127	        "observed"
128	      } else {
129	        "partial"
130	      },
131	      evidence={
132	        "templates": diagnostic_env,
133	        "references": observed.unwrap_or(Json::null()),
134	        "completeness": if complete {
135	          "complete"
136	        } else {
137	          "partial"
138	        },
139	        "missingReason": if complete {
140	          Json::null()
141	        } else if observed is None || observation_error {
142	          "observation_failed"
143	        } else {
144	          "value_truncated"
145	        },
146	        "truncatedReferences": truncated,
147	      },
148	      recording~,
149	    )
150	  }
151	  guard status == 0 else {
152	    raise AdapterError(command_failure("orca-serve", status, detail))
153	  }
154	  let result = @json.parse(output)
155	  let connection = match field(result, "connection") {
156	    Some(value) => value
157	    None => result
158	  }
159	  guard required(connection, "pairingCode") != "" else {
160	    raise AdapterError("Orca returned no pairing code")
161	  }
162	  @fs.write_file(
163	    required(state, "tunnelDirectory") + "/pairing-code",
164	    required(connection, "pairingCode"),
165	    permission=0o600,
166	  )
167	  let output : Json = {
168	    "type": "orca-server",
169	    "pairingCode": required(connection, "pairingCode"),
170	    "projectRoot": root,
171	  }
172	  output
173	}
